//! GFX10 (RDNA2) texture tiling for 2D surfaces, from AMD addrlib swizzle patterns
//! (`tiling_tables.rs`, generated by scripts/gen_tiling.py).
//!
//! A pattern gives every address bit inside a block as the XOR of some x / y bits, so the
//! offset is linear over GF(2): `offset(x, y) = ox[x] ^ oy[y]`, two small tables per layout.
//! Blocks (256 B / 4 KB / 64 KB) are laid out row-major. Mip chains and slices are the
//! caller's business (each level is its own surface at its own offset).

use super::tiling_tables::{NIBBLE01, NIBBLE2, NIBBLE3, NIBBLE4, PATTERNS};

/// The part of GB_ADDR_CONFIG the XOR modes depend on (number of pipes and packers, log2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PipeConfig {
    pub pipes_log2: u32,
    pub pkrs_log2: u32,
}

impl PipeConfig {
    /// row group in the RB+ tables (addrlib Gfx10Lib::HwlInitGlobalParams, m_colorBaseIndex)
    fn group(self) -> usize {
        (self.pipes_log2
            + if self.pkrs_log2 >= 2 {
                2 * self.pkrs_log2 - 2
            } else {
                0
            }) as usize
    }
}

/// GFX10 SW_MODE values with an XOR (pipe / bank) component
fn is_xor(mode: u32) -> bool {
    mode >= 16
}

fn block_log2(mode: u32) -> Option<u32> {
    Some(match mode {
        1 | 2 => 8,
        5 | 6 | 21 | 22 => 12,
        9 | 10 | 17 | 18 | 24..=27 => 16,
        _ => return None,
    })
}

/// How one tiled 2D surface of `1 << elem_log2`-byte elements (pixels, or 4×4 blocks for BCn)
/// maps to memory.
#[derive(Clone, Debug)]
pub struct Layout {
    pub mode: u32,
    pub elem_log2: u32,
    /// block size in elements
    pub block_w: usize,
    pub block_h: usize,
    pub block_bytes: usize,
    /// XORed into every in-block byte offset: the pipe / bank swizzle a T# base address carries
    /// in its low bits (`base & (block_bytes - 1)`), 0 otherwise
    pub base_xor: usize,
    ox: Vec<u32>,
    oy: Vec<u32>,
}

impl Layout {
    /// `None` for linear (0), unknown / reserved modes, 3D-only modes and elements over 16 B.
    pub fn new(mode: u32, elem_log2: u32, cfg: PipeConfig) -> Option<Layout> {
        let blk = block_log2(mode)?;
        if elem_log2 > 4 {
            return None;
        }
        let rows = PATTERNS.iter().find(|p| p.0 == mode)?.1;
        let row = if is_xor(mode) { cfg.group() * 5 } else { 0 } + elem_log2 as usize;
        let idx = rows.get(row)?;
        let mut bits = [0u64; 20];
        bits[..8].copy_from_slice(&NIBBLE01[idx[0] as usize]);
        bits[8..12].copy_from_slice(&NIBBLE2[idx[1] as usize]);
        bits[12..16].copy_from_slice(&NIBBLE3[idx[2] as usize]);
        bits[16..20].copy_from_slice(&NIBBLE4[idx[3] as usize]);
        // block size in elements: 256 B micro block, grown evenly in both directions
        let (w256, h256) = [(4, 4), (4, 3), (3, 3), (3, 2), (2, 2)][elem_log2 as usize];
        let amp = blk - 8;
        let (wl, hl) = (w256 + amp / 2, h256 + amp - amp / 2);
        let (bw, bh) = (1usize << wl, 1usize << hl);
        let table = |n: usize, shift: u32| -> Vec<u32> {
            (0..n as u32)
                .map(|c| {
                    let mut off = 0u32;
                    for (i, &b) in bits[..blk as usize].iter().enumerate() {
                        let mask = ((b >> shift) & 0xFFFF) as u32;
                        off |= ((mask & c).count_ones() & 1) << i;
                    }
                    off
                })
                .collect()
        };
        Some(Layout {
            mode,
            elem_log2,
            block_w: bw,
            block_h: bh,
            block_bytes: 1 << blk,
            base_xor: 0,
            ox: table(bw, 0),
            oy: table(bh, 16),
        })
    }

    /// surface `w` × `h` elements: (blocks per row, blocks per column)
    pub fn blocks(&self, w: usize, h: usize) -> (usize, usize) {
        (w.div_ceil(self.block_w), h.div_ceil(self.block_h))
    }

    /// bytes the tiled surface occupies (padded to whole blocks)
    pub fn size(&self, w: usize, h: usize) -> usize {
        let (bx, by) = self.blocks(w, h);
        bx * by * self.block_bytes
    }

    /// byte offset of element (x, y) in a surface `w` elements wide
    pub fn offset(&self, x: usize, y: usize, w: usize) -> usize {
        let pitch_blocks = w.div_ceil(self.block_w);
        let block = (y / self.block_h) * pitch_blocks + x / self.block_w;
        block * self.block_bytes
            + ((self.ox[x % self.block_w] ^ self.oy[y % self.block_h]) as usize ^ self.base_xor)
    }

    /// tiled → linear rows (`w << elem_log2` bytes each); bytes past the end of `src` read as 0
    pub fn detile(&self, src: &[u8], w: usize, h: usize) -> Vec<u8> {
        let e = 1usize << self.elem_log2;
        let mut out = vec![0u8; w * h * e];
        for y in 0..h {
            for x in 0..w {
                let o = self.offset(x, y, w);
                if let Some(s) = src.get(o..o + e) {
                    let d = (y * w + x) * e;
                    out[d..d + e].copy_from_slice(s);
                }
            }
        }
        out
    }

    /// linear rows → tiled (the inverse of `detile`)
    pub fn tile(&self, linear: &[u8], w: usize, h: usize) -> Vec<u8> {
        let e = 1usize << self.elem_log2;
        let mut out = vec![0u8; self.size(w, h)];
        for y in 0..h {
            for x in 0..w {
                let o = self.offset(x, y, w);
                let s = (y * w + x) * e;
                out[o..o + e].copy_from_slice(&linear[s..s + e]);
            }
        }
        out
    }
}

/// Element of a GFX10 IMG_FORMAT: (log2 bytes, side in pixels: 1, or 4 for BCn blocks).
/// `None` for 96-bit formats (not tiled with these patterns) and unknown ones.
pub fn element(format: u32) -> Option<(u32, u32)> {
    Some(match format {
        1..=6 => (0, 1),
        7..=19 | 133..=136 => (1, 1),
        20..=61 | 130 | 132 => (2, 1),
        62..=71 => (3, 1),
        75..=77 => (4, 1),
        169 | 170 | 175 | 176 => (3, 4),
        171..=174 | 177..=182 => (4, 4),
        _ => return None,
    })
}

/// Layout of mip 0 of a T#'s image plus its size in elements. The swizzle the base address
/// carries below the block size becomes `base_xor`; the data starts at
/// `address & !(block_bytes - 1)`.
pub fn image_layout(t: &super::desc::Image, cfg: PipeConfig) -> Option<(Layout, usize, usize)> {
    let (e, side) = element(t.format)?;
    let mut l = Layout::new(t.swizzle_mode, e, cfg)?;
    l.base_xor = (t.address as usize) & (l.block_bytes - 1);
    Some((
        l,
        t.width.div_ceil(side) as usize,
        t.height.div_ceil(side) as usize,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    const MODES: [u32; 14] = [1, 2, 5, 6, 9, 10, 17, 18, 21, 22, 24, 25, 26, 27];

    fn configs() -> Vec<PipeConfig> {
        let mut v = vec![];
        for (p, k) in [
            (0, 0),
            (1, 0),
            (2, 0),
            (3, 1),
            (2, 2),
            (3, 2),
            (4, 2),
            (3, 3),
            (4, 3),
            (5, 3),
        ] {
            v.push(PipeConfig {
                pipes_log2: p,
                pkrs_log2: k,
            });
        }
        v
    }

    /// every mode, element size and pipe configuration: the in-block mapping is a permutation
    /// of the block's elements (catches a mis-parsed table or a wrong block shape)
    #[test]
    fn every_pattern_is_a_permutation_of_its_block() {
        for mode in MODES {
            for e in 0..5 {
                for cfg in configs() {
                    let l = Layout::new(mode, e, cfg).unwrap();
                    assert_eq!(
                        l.block_w * l.block_h << e,
                        l.block_bytes,
                        "mode {mode} e {e}"
                    );
                    let mut seen = vec![false; l.block_bytes >> e];
                    for y in 0..l.block_h {
                        for x in 0..l.block_w {
                            let o = l.offset(x, y, l.block_w);
                            assert_eq!(
                                o & ((1 << e) - 1),
                                0,
                                "mode {mode} e {e} {cfg:?}: misaligned"
                            );
                            assert!(
                                !std::mem::replace(&mut seen[o >> e], true),
                                "mode {mode} e {e} {cfg:?}: ({x},{y}) collides"
                            );
                        }
                    }
                }
            }
        }
    }

    /// SW_256B_S with bytes: a 16×16 block stored row by row (addrlib's first nibble row)
    #[test]
    fn sw_256b_s_bytes_are_row_major() {
        let l = Layout::new(
            1,
            0,
            PipeConfig {
                pipes_log2: 0,
                pkrs_log2: 0,
            },
        )
        .unwrap();
        assert_eq!((l.block_w, l.block_h), (16, 16));
        assert_eq!(l.offset(5, 3, 16), 3 * 16 + 5);
        assert_eq!(l.offset(1, 16, 32), 2 * 256 + 1); // second block row of a 2-block-wide surface
    }

    #[test]
    fn t_sharp_bc7_layout() {
        let t = crate::gpu::desc::Image {
            address: 0x1_2345_0000 | 0x300,
            format: 181,
            width: 256,
            height: 130,
            depth: 1,
            ty: crate::gpu::desc::ImageType::D2,
            base_level: 0,
            last_level: 0,
            max_mip: 0,
            base_array: 0,
            dst_sel: [4, 5, 6, 7],
            swizzle_mode: 10,
            min_lod: 0.0,
        };
        let (l, w, h) = image_layout(
            &t,
            PipeConfig {
                pipes_log2: 0,
                pkrs_log2: 0,
            },
        )
        .unwrap();
        assert_eq!(
            (w, h, l.block_w, l.block_h, l.base_xor),
            (64, 33, 64, 64, 0x300)
        );
        assert_eq!(l.size(w, h), 65536); // 33 block rows fit one 64×64 tile
        assert_eq!(element(56), Some((2, 1)));
        assert_eq!(element(72), None);
    }

    #[test]
    fn tile_then_detile_round_trips_with_partial_blocks() {
        let l = Layout::new(
            25,
            2,
            PipeConfig {
                pipes_log2: 4,
                pkrs_log2: 2,
            },
        )
        .unwrap();
        let (w, h) = (200, 130);
        let lin: Vec<u8> = (0..w * h * 4).map(|i| (i * 7 + i / 977) as u8).collect();
        let t = l.tile(&lin, w, h);
        assert_eq!(t.len(), 2 * 2 * 65536);
        assert_eq!(l.detile(&t, w, h), lin);
    }

    /// The patterns the TTPF viewer found by eye on retail console textures (tools/ttpf-viewer
    /// tile.rs) are addrlib's SW_64KB_D (64 KB tiles) and SW_4KB_S (4 KB tiles), bit for bit.
    #[test]
    fn standard_swizzle_matches_the_retail_texture_patterns() {
        let retail: [(u32, u32, &str); 10] = [
            (10, 4, "xyxyyxyxyxyx"),
            (5, 4, "yyxxyxyx"),
            (10, 3, "xyxxyyxyxyxyx"),
            (5, 3, "xyyxxyxyx"),
            (10, 2, "xxyyxyyxyxyxyx"),
            (5, 2, "xxyyyxyxyx"),
            (10, 1, "xxxyyyxyxyxyxyx"),
            (5, 1, "xxxyyyxyxyx"),
            (10, 0, "xxxyyyxyyxyxyxyx"),
            (5, 0, "xxxxyyyyyxyx"),
        ];
        for (mode, e, want) in retail {
            let l = Layout::new(
                mode,
                e,
                PipeConfig {
                    pipes_log2: 0,
                    pkrs_log2: 0,
                },
            )
            .unwrap();
            // bit i of the element index: which coordinate moves it
            let got: String = (0..want.len())
                .map(|i| {
                    let bit = 1u32 << (i as u32 + e);
                    if l.ox.iter().any(|&o| o == bit) {
                        'x'
                    } else if l.oy.iter().any(|&o| o == bit) {
                        'y'
                    } else {
                        '?'
                    }
                })
                .collect();
            assert_eq!(got, want, "mode {mode}, {} B elements", 1 << e);
        }
    }
}
